import React from 'react';
import SectionHeading from './SectionHeading';
import Reveal from './Reveal';
import Icon from './icons';
import { interests } from '../data/content';

export default function Interests() {
  return (
    <section id="interests" className="py-20 px-4 sm:px-6">
      <div className="max-w-6xl mx-auto">
        <Reveal>
          <SectionHeading eyebrow={interests.eyebrow} heading={interests.heading} />
        </Reveal>

        <div className="mt-8 grid sm:grid-cols-2 gap-4">
          {interests.cards.map((card, idx) => (
            <Reveal key={card.title} delay={(idx % 2) * 80}>
              <div className="h-full rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 p-6 transition-transform hover:-translate-y-1 hover:shadow-md">
                <div className="inline-flex items-center justify-center w-9 h-9 rounded-lg bg-indigo-500/10 text-indigo-500 dark:text-indigo-400 mb-3">
                  <Icon name={card.icon} size={18} />
                </div>
                <h3 className="font-display font-semibold text-zinc-900 dark:text-zinc-50">{card.title}</h3>
                <p className="mt-1.5 text-sm text-zinc-600 dark:text-zinc-400 leading-relaxed">
                  {card.description}
                </p>
              </div>
            </Reveal>
          ))}
        </div>
      </div>
    </section>
  );
}
